#!/usr/bin/env python3
"""
Guarded patch: wire all 15 remaining skill background patterns (extracted
from the user-provided composite reference image) in one pass, using the
same true-tiling approach (ImageShader + TileMode.Repeated) established
for Mining. Writes 15 drawable resources, adds 15 themed-background
Composable functions, and extends skillPatternBackground's dispatch.
"""
import os
import base64

REPO_ROOT = "."
DRAWABLE_DIR = os.path.join(REPO_ROOT, "app/src/main/res/drawable")
PATTERN_BG_PATH = os.path.join(REPO_ROOT, "app/src/main/kotlin/com/yourname/idlerpg/PatternBackground.kt")

IMAGES = {
    "WOODCUTTING": """""",
    "FISHING": """""",
    "FARMING": """""",
    "THIEVING": """""",
    "SMITHING": """""",
    "COOKING": """""",
    "CRAFTING": """""",
    "FLETCHING": """""",
    "ALCHEMY": """""",
    "MAGIC": """""",
    "ATTACK": """""",
    "STRENGTH": """""",
    "DEFENSE": """""",
    "PRAYER": """""",
    "ARCHERY": """""",
}


os.makedirs(DRAWABLE_DIR, exist_ok=True)
for skill_upper, b64 in IMAGES.items():
    name = skill_upper.lower()
    path = os.path.join(DRAWABLE_DIR, f"bg_{name}_pattern.webp")
    data = base64.b64decode(b64)
    if os.path.exists(path) and os.path.getsize(path) == len(data):
        print(f"SKIP (already present, same size): {path}")
        continue
    with open(path, "wb") as f:
        f.write(data)
    print(f"WROTE: {path} ({len(data)} bytes)")

with open(PATTERN_BG_PATH, "r", encoding="utf-8") as f:
    content = f.read()


def guarded_replace(content, old, new, marker):
    if marker in content:
        print(f"SKIP (already applied): {marker[:50]}")
        return content
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly 1 match, found {count}.\n--- old_str ---\n{old}\n--- end ---")
    print(f"PATCHED: {marker[:50]}")
    return content.replace(old, new)


# Insert the 15 new themed-background functions right before miningThemedBackground's
# comment block, so they all live together.
